/**
 * build-player-photos.mjs — resolve an official Premier League headshot for
 * every player named in the Higher or Lower pool, and write the result to
 * src/data/games/player-photos.json.
 *
 *   node scripts/games/build-player-photos.mjs          # write
 *   node scripts/games/build-player-photos.mjs --dry    # report only
 *
 * WHY A SIDECAR, not a field inside pool.json: the pool is regenerated by its
 * own pipeline, and anything written into it would be lost on the next rebuild.
 * This file is keyed by NAME, so it survives a pool rebuild and can be
 * refreshed on its own whenever the squad lists move.
 *
 * WHY NOT RESOLVE AT RUNTIME: the home hero renders this. A live lookup per
 * player would put two external calls on the critical path of the busiest page
 * in the app, and hand it a failure mode it doesn't need. Baked in, it costs
 * nothing and cannot fail.
 *
 * WHY FPL AND NOT A NAME SEARCH: TheSportsDB's searchplayers endpoint (used by
 * lib/playerImages.ts for national-team cutouts) returns *a* player for almost
 * any surname — measured 2026-07-24, 8 of 20 pool names came back as the wrong
 * person, including "Saka" as Fabrice N'Sakala and "N.Williams" as a retired
 * cricketer. FPL's element list is the actual Premier League squad set, so a
 * name that matches is the right human.
 */

import fs from "node:fs";
import path from "node:path";

const POOL = path.join(process.cwd(), "src/data/games/pool.json");
const OUT = path.join(process.cwd(), "src/data/games/player-photos.json");
const DRY = process.argv.includes("--dry");
const SM_KEY = process.env.SPORTMONKS_API_KEY;
const SM_SEASON = 28083; // Premier League 2026/27 (matches build-pool.mjs)

// FPL short club names → SportMonks full names, for the fallback join below.
const CLUB_ALIASES = {
  "Man City": "Manchester City",
  "Man Utd": "Manchester United",
  "Nott'm Forest": "Nottingham Forest",
  Spurs: "Tottenham Hotspur",
};

/** Strip accents/punctuation so "Enes Ünal" and "Enes Unal" are one key. */
const norm = (s) =>
  s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z]/g, "");

/** Surname key: last token, minus an initial like "M." or "J.". */
const surnameKey = (label) => norm(label.split(" ").pop().replace(/^[A-Z]\.?$/, "") || label);

/**
 * Pool labels that are abbreviations or club-disambiguated forms of an FPL
 * web_name. Everything else is left to fail rather than guessed at — a wrong
 * face next to a name is worse than no face.
 */
const ALIASES = {
  "Ederson M.": "Ederson",
  "C.Miguel": "Carlos Miguel",
  "Bruno G.": "Bruno Guimaraes",
  "M.Salah": "Salah",
  "N.Williams": "Neco Williams",
  "J.Timber": "Timber",
  "G.Jesus": "Jesus",
  "L.Guilherme": "Luis Guilherme",
  "M.Fernandes": "Matheus Fernandes",
  "Virgil": "Van Dijk",
};

/**
 * SportMonks squad images, keyed club → surname → [{name, image}]. The FALLBACK
 * source for players the PL CDN has no headshot for (newer signings, mostly).
 * Matched club-constrained by surname, exactly like the age join in
 * build-pool.mjs, so a match is one of ~25 players at that club, not a global
 * name search — that is what keeps it from putting the wrong face on a name.
 */
async function sportmonksImages() {
  if (!SM_KEY) { console.warn("! SPORTMONKS_API_KEY missing — no image fallback, coverage will be lower"); return new Map(); }
  const teams = (await (await fetch(`https://api.sportmonks.com/v3/football/teams/seasons/${SM_SEASON}?api_token=${SM_KEY}`)).json()).data ?? [];
  const byClub = new Map();
  for (const t of teams) {
    const sq = (await (await fetch(`https://api.sportmonks.com/v3/football/squads/seasons/${SM_SEASON}/teams/${t.id}?api_token=${SM_KEY}&include=player`)).json()).data ?? [];
    const m = new Map();
    for (const row of sq) {
      const p = row.player ?? {};
      // SportMonks serves a generic silhouette (placeholder.png) for players
      // with no real photo. It returns 200, so the image-load check can't catch
      // it — reject by name. A silhouette next to a real name is as wrong as a
      // broken image (Cardines, Yohanna both got it, 2026-07-24).
      if (!p.display_name || !p.image_path || p.image_path.includes("placeholder")) continue;
      const k = norm(p.display_name.split(" ").pop());
      if (!m.has(k)) m.set(k, []);
      m.get(k).push({ name: p.display_name, image: p.image_path });
    }
    byClub.set(norm(t.name), m);
  }
  return byClub;
}

async function main() {
  const pool = JSON.parse(fs.readFileSync(POOL, "utf8"));
  // Every Higher or Lower topic, including FPL points (legacy "this-season-form"
  // format) — those players can headline the daily tile too.
  const hl = pool.questions.filter((q) => q.format === "higher-lower" || q.stat === "points");

  const res = await fetch("https://fantasy.premierleague.com/api/bootstrap-static/");
  if (!res.ok) throw new Error(`FPL bootstrap failed: ${res.status}`);
  const fpl = await res.json();

  // Common surnames repeat across clubs (Palmer, Bowen, Salah, Johnson...), so
  // keep every candidate and disambiguate on club below. Dropping duplicates
  // outright cost ~7% of questions and threw away the biggest names in the game.
  const teamName = new Map(fpl.teams.map((t) => [t.id, t.name]));
  const byName = new Map();
  for (const e of fpl.elements) {
    const k = norm(e.web_name);
    if (!byName.has(k)) byName.set(k, []);
    byName.get(k).push({ code: e.code, club: teamName.get(e.team), web: e.web_name });
  }

  // Roster fallback: pool options carry an id into pool.currentPlayers, whose
  // `name` is sometimes fuller than the option label.
  const roster = new Map((pool.currentPlayers ?? []).map((p) => [p.id, p]));

  const labels = new Map(); // label -> option ids that use it
  for (const q of hl) {
    for (const o of q.options) {
      if (!labels.has(o.label)) labels.set(o.label, []);
      labels.get(o.label).push(o.id);
    }
  }

  const resolved = new Map(); // normalised label -> FPL code (before image verify)
  const labelClub = new Map(); // normalised label -> club, for the SportMonks fallback
  const labelText = new Map(); // normalised label -> original text, for surname matching
  const missed = [];
  const ambiguous = [];
  for (const [label, ids] of labels) {
    // The club the pool believes this player is at, when it knows one. It is
    // the only thing that separates Cole Palmer from Liam Palmer.
    const club = ids.map((id) => roster.get(id)?.club).find(Boolean) ?? null;
    labelClub.set(norm(label), club);
    labelText.set(norm(label), label);
    const candidates = [
      ALIASES[label] ?? label,
      label,
      ...ids.map((id) => roster.get(id)?.name).filter(Boolean),
    ];

    let picked = null;
    for (const c of candidates) {
      const hits = byName.get(norm(c));
      if (!hits?.length) continue;
      if (hits.length === 1) { picked = hits[0]; break; }
      const byClub = club ? hits.filter((h) => h.club === club) : [];
      if (byClub.length === 1) { picked = byClub[0]; break; }
      // Name repeats and nothing separates them: skip rather than coin-flip.
      ambiguous.push(`${label}${club ? ` (${club})` : ""} → ${hits.map((h) => h.club).join(" / ")}`);
      break;
    }

    if (picked) resolved.set(norm(label), picked.code);
    else missed.push(label);
  }

  // A resolved FPL code is NOT a guarantee the headshot exists. The PL CDN does
  // not generate every size for every player: Van Dijk (p97032) has a 110x140
  // but no 250x250, and newer signings (Boscagli, Wirtz, Woltemade) have
  // neither. Shipped once with 250x250 assumed-present, which put a real face
  // next to a broken image on the daily tile (Van de Ven v Boscagli, 2026-07-24).
  //
  // So VERIFY. Try the sharp size first, fall back to the small one, and store
  // the URL that actually loads. A code whose image 403s at both sizes is
  // dropped, and the "both faces or neither" gate then falls the pair back to
  // plain names — never a broken image.
  const SIZES = ["250x250", "110x140"];
  const urlFor = (size, code) =>
    `https://resources.premierleague.com/premierleague/photos/players/${size}/p${code}.png`;

  async function firstLoadable(code) {
    for (const size of SIZES) {
      try {
        const r = await fetch(urlFor(size, code));
        if (r.status === 200 && (r.headers.get("content-type") || "").includes("image")) {
          return urlFor(size, code);
        }
      } catch { /* network blip — treat as absent */ }
    }
    return null;
  }

  const photos = {};
  const dead = [];
  const entries = [...resolved.entries()];
  const queue = [...entries];
  async function worker() {
    while (queue.length) {
      const [key, code] = queue.shift();
      const url = await firstLoadable(code);
      if (url) photos[key] = url;
      else dead.push(`${key}:${code}`);
    }
  }
  await Promise.all(Array.from({ length: 10 }, worker)); // bounded concurrency

  // FALLBACK: for players the PL CDN has no headshot for, use SportMonks' own
  // image. Matched club-constrained by surname (a name repeated across clubs
  // can't collide) and — same lesson as above — only kept if the image loads.
  const smByClub = await sportmonksImages();
  // FPL and SportMonks spell some clubs differently ("Newcastle" vs "Newcastle
  // United", "Wolves" vs "Wolverhampton Wanderers"). Resolve exact first, then
  // by containment either way — the same tolerant match build-pool.mjs uses for
  // ages, without which every Newcastle/Wolves/West Ham player was lost.
  const smClubKeys = [...smByClub.keys()];
  const smSquadFor = (fplClub) => {
    const want = norm(CLUB_ALIASES[fplClub] ?? fplClub);
    if (smByClub.has(want)) return smByClub.get(want);
    const hit = smClubKeys.find((k) => k.includes(want) || want.includes(k));
    return hit ? smByClub.get(hit) : null;
  };

  const labelsWithoutPhoto = [...resolved.keys()].filter((k) => !photos[k]);
  let recovered = 0, smAmbiguous = 0, smDead = 0;
  await Promise.all(labelsWithoutPhoto.map(async (key) => {
    const club = labelClub.get(key);
    if (!club) return;
    const cands = smSquadFor(club)?.get(surnameKey(labelText.get(key) ?? key));
    if (!cands?.length) return;
    if (cands.length > 1) { smAmbiguous++; return; } // two same-surname at one club — don't guess
    const img = cands[0].image;
    try {
      const r = await fetch(img);
      if (r.status === 200 && (r.headers.get("content-type") || "").includes("image")) {
        photos[key] = img;
        recovered++;
      } else smDead++;
    } catch { smDead++; }
  }));

  // Per-question coverage is the number that decides the UI: a tile with one
  // face and one blank is worse than a tile with neither.
  let both = 0, one = 0, none = 0;
  for (const q of hl) {
    const n = q.options.filter((o) => photos[norm(o.label)]).length;
    if (n === 2) both++; else if (n === 1) one++; else none++;
  }

  console.log(`players named in Higher or Lower: ${labels.size}`);
  console.log(`resolved to an FPL code:          ${resolved.size}`);
  console.log(`PL headshot loads:                ${Object.keys(photos).length - recovered}`);
  console.log(`recovered via SportMonks:         ${recovered} (ambiguous ${smAmbiguous}, no/broken img ${smDead})`);
  console.log(`total with a LOADABLE image:      ${Object.keys(photos).length}`);
  console.log(`questions with BOTH faces:        ${both}/${hl.length} (${(100 * both / hl.length).toFixed(1)}%)`);
  console.log(`               one face:          ${one}`);
  console.log(`               no faces:          ${none}`);
  if (missed.length) console.log(`\nunresolved (${missed.length}): ${missed.join(", ")}`);
  if (ambiguous.length) console.log(`\nambiguous, skipped (${ambiguous.length}): ${ambiguous.join(" · ")}`);
  if (dead.length) console.log(`\nno image at any size (${dead.length}): ${dead.join(", ")}`);

  if (DRY) { console.log("\n--dry: nothing written"); return; }

  fs.writeFileSync(
    OUT,
    JSON.stringify(
      {
        builtAt: new Date().toISOString(),
        source: "fantasy.premierleague.com/api/bootstrap-static",
        note: "key = normalised pool option label, value = a VERIFIED-loadable PL headshot URL",
        photos,
      },
      null,
      1
    ) + "\n"
  );
  console.log(`\nwrote ${OUT}`);
}

main().catch((e) => { console.error(e); process.exit(1); });
